replacements.newText:
/* ---------- < 1024px: an editorial frame around the 3D figure ----------
   Headline at the top under the menu, the figure free in the middle, the
   supporting copy and the button anchored at the bottom (above the scroll hint). */
@media (max-width: 1023px) {
  .hlab-vx-ov .hlab-vx-title, .hlab-vx-ov .hlab-vx-cluster, .hlab-vx-ov .hlab-vx-support, .hlab-vx-ov .hlab-vx-tagline,
  .hlab-vx-ov-brain .hlab-vx-tl-left, .hlab-vx-ov-brain .hlab-vx-tl-right, .hlab-vx-ov-brain .hlab-vx-flank-left,
  .hlab-vx-ov-brain .hlab-vx-flank-right, .hlab-vx-ov .hlab-vx-cta, .hlab-vx-ov-hero .hlab-vx-tags,
  .hlab-vx-ov-galaxy .hlab-vx-stat { position: static; width: auto !important; transform: none !important; }
  .hlab-vx-ov { display: flex; flex-direction: column; align-items: flex-start;
    padding: calc(env(safe-area-inset-top, 0px) + 6.75rem) 1.5rem calc(env(safe-area-inset-bottom, 0px) + 6.5rem); }
  .hlab-vx-ov .hlab-vx-title, .hlab-vx-ov-brain .hlab-vx-tl-left, .hlab-vx-ov-brain .hlab-vx-tl-right {
    font-size: clamp(2.25rem, 10vw, 3.5rem) !important; line-height: .96; text-align: left; max-width: 12ch; }
  .hlab-vx-ov .hlab-vx-support { font-size: .9375rem; line-height: 1.45; max-width: 30ch; text-align: left; color: rgba(255,255,255,.86); }
  .hlab-vx-ov .hlab-vx-tw.hlab-vx-center { justify-content: flex-start; }

  /* orb: eyebrow + headline | figure | tags, support + button */
  .hlab-vx-ov-hero .hlab-vx-cluster { display: contents; }
  .hlab-vx-ov-hero .hlab-vx-tagline { order: 1; max-width: 46ch; margin-bottom: 1rem; font-size: .6875rem; line-height: 1.5;
    letter-spacing: .14em; color: rgba(255,255,255,.7); }
  .hlab-vx-ov-hero .hlab-vx-title { order: 2; max-width: 9.6em; }   /* three lines at any size: "une" starts the last one */
  .hlab-vx-ov-hero .hlab-vx-tags { order: 3; margin-top: auto; gap: .625rem; flex-wrap: wrap; font-size: .6875rem; letter-spacing: .06em; color: rgba(255,255,255,.7); }
  .hlab-vx-ov-hero .hlab-vx-tags i { width: 3px; height: 3px; opacity: .7; }
  .hlab-vx-ov-hero .hlab-vx-support { order: 4; margin-top: 1rem; }
  .hlab-vx-ov-hero .hlab-vx-cta { order: 5; margin-top: 1.25rem; }

  /* galaxy: headline | figure | support, then the four services in one row */
  .hlab-vx-ov-galaxy .hlab-vx-title { font-size: clamp(1.625rem, 6.8vw, 2.75rem) !important; line-height: 1; max-width: 18ch; }
  .hlab-vx-ov-galaxy .hlab-vx-cluster { margin-top: auto; width: 100%; height: auto; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1.25rem .75rem; }
  .hlab-vx-ov-galaxy .hlab-vx-support { grid-column: 1 / -1; }
  .hlab-vx-ov-galaxy .hlab-vx-rule, .hlab-vx-ov-galaxy .hlab-vx-vrule { display: none; }
  .hlab-vx-ov-galaxy .hlab-vx-stat { border-left: 0; border-top: 1px solid rgba(255,255,255,.28); padding: .625rem 0 0; gap: .3rem; }
  .hlab-vx-ov-galaxy .hlab-vx-v { font-size: 1.125rem; }
  .hlab-vx-ov-galaxy .hlab-vx-l { font-size: .6875rem; line-height: 1.3; color: rgba(255,255,255,.72); }

  /* brain: the sentence wraps the figure, top left to bottom right */
  .hlab-vx-ov-brain .hlab-vx-flank-right { order: 1; margin-bottom: 1rem; font-size: .6875rem; letter-spacing: .14em; color: rgba(255,255,255,.7); justify-content: flex-start; }
  .hlab-vx-ov-brain .hlab-vx-tl-left { order: 2; }
  .hlab-vx-ov-brain .hlab-vx-tl-right { order: 3; margin-top: auto; align-self: flex-end; text-align: right; }
  .hlab-vx-ov-brain .hlab-vx-flank-left { order: 4; align-self: flex-end; max-width: 30ch; margin-top: 1rem; font-size: .75rem; line-height: 1.45;
    letter-spacing: .04em; text-align: right; justify-content: flex-end; color: rgba(255,255,255,.8); }
  .hlab-vx-ov-brain .hlab-vx-cta { order: 5; align-self: flex-end; margin-top: 1.25rem; }

  .hlab-vx-send { height: 3.25rem; gap: .875rem; padding: 0 .3125rem 0 1.5rem; }
  .hlab-vx-send .hlab-vx-fill { padding: 0; font-size: 1rem; }
  .hlab-vx-send .hlab-vx-arrow { width: 2.625rem; height: 2.625rem; font-size: 0; }
}
/* shorter phones (the figure scales with the screen height, the copy does not) */
@media (max-width: 1023px) and (max-height: 780px) {
  .hlab-vx-ov { padding-top: calc(env(safe-area-inset-top, 0px) + 6.25rem); padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 5.75rem); }
  .hlab-vx-ov .hlab-vx-title, .hlab-vx-ov-brain .hlab-vx-tl-left, .hlab-vx-ov-brain .hlab-vx-tl-right { font-size: clamp(1.875rem, 9vw, 2.25rem) !important; }
  .hlab-vx-ov-galaxy .hlab-vx-title { font-size: clamp(1.5rem, 6.4vw, 1.75rem) !important; }
  .hlab-vx-ov .hlab-vx-support { font-size: .875rem; }
  .hlab-vx-ov-hero .hlab-vx-tagline { margin-bottom: .75rem; }
}
@media (max-width: 1023px) and (max-height: 700px) {
  .hlab-vx-ov-hero .hlab-vx-tags { display: none; }
  .hlab-vx-ov-hero .hlab-vx-support { margin-top: auto; }
}
/* phones held sideways: less frame, smaller headline */
@media (max-width: 1023px) and (max-height: 560px) {
  .hlab-vx-ov { padding: calc(env(safe-area-inset-top, 0px) + 5.25rem) 1.5rem 1.25rem; }
  .hlab-vx-ov .hlab-vx-title, .hlab-vx-ov-brain .hlab-vx-tl-left, .hlab-vx-ov-brain .hlab-vx-tl-right { font-size: clamp(1.5rem, 7vh, 2.25rem) !important; max-width: 20ch; }
  .hlab-vx-ov-hero .hlab-vx-tags, .hlab-vx-ov-brain .hlab-vx-flank-left { display: none; }
}
